arguments.command:
cd /tmp && curl -sS -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" -d "types=public_channel,private_channel&limit=1000" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d); sys.exit(1)
for c in d['channels']:
    if 'launch' in c['name'].lower() or 'readiness' in c['name'].lower():
        print(c['id'], c['name'], c.get('is_archived'))
"

